values
  ('b893031a-9ea6-5a4b-ba73-3217557936e8', 'essential_medical:core:anatomy:noun:ess-core-anatomy-001', '63bd273d-812c-5170-a494-c4bc2c405567', 'In class the tutor pointed to the anatomy while explaining the adjacent organ.', 'anatomy', 'Here the term names the study of body structure.', '这里指解剖学。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
