  ('ed941421-40bb-5e70-aa6b-851954cc5ff6', 'essential_medical:core:embryology:noun:ess-core-embryology-001', 'eb933809-0b21-5651-a751-f175556ed61f', 'The ward round paused on the embryology so juniors could name it correctly.', 'embryology', 'Here the term names the study of development before birth.', '这里指胚胎学。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('2c657152-4eee-5907-a37d-1dd04d11cf8b', 'essential_medical:core:hematology:noun:ess-core-hematology-001', '43c809da-0f3c-5fd7-896d-2e08f4f5ff5e', 'The textbook figure labels the hematology beside the neighboring tissue.', 'hematology', 'Here the term names the study of blood and blood-forming organs.', '这里指血液学。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('76ef7f9e-d57e-581d-aff2-fda8186dbc66', 'essential_medical:core:immunology:noun:ess-core-immunology-001', '61d2af70-9b12-5708-ad9d-0541b5c255d1', 'After history taking, the intern wrote the immunology into the problem list.', 'immunology', 'Here the term names the study of host defense against infection.', '这里指免疫学。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
