  ('93f73680-1afd-5d9d-b573-8a01acefe3fb', 'essential_medical:core:biology:noun:ess-core-biology-001', 'e0b2b0d6-24b6-5ed1-932c-3a908ce63eec', 'A short case note mentioned the biology before listing later findings.', 'biology', 'Here the term names the study of living organisms.', '这里指生物学。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('31fee249-b3d3-5de0-9333-31aee9d04822', 'essential_medical:core:cardiovascular:adjective:ess-core-cardiovascular-001', '79e7630a-a699-5899-870f-d0341c8946f7', 'The textbook warns not to write cardiovascular unless the evidence actually fits.', 'cardiovascular', 'The classroom note used this word to say the finding was relating to the heart and blood vessels.', '课堂记录把这一发现写成「心血管的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('810bd39d-787d-5d6f-8d0e-ca56a8be7f9c', 'essential_medical:core:lymphatic:adjective:ess-core-lymphatic-001', 'd0777f1b-a026-5e47-9cf5-8b5ea6324d64', 'Her presentation stayed lymphatic from admission through the first night.', 'lymphatic', 'The classroom note used this word to say the finding was relating to lymph or lymphatic vessels.', '课堂记录把这一发现写成「淋巴的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('8731acd7-128f-5d4a-92e2-ff9ffedd3493', 'essential_medical:core:circulatory:adjective:ess-core-circulatory-001', '22e552e4-167c-576a-a151-0ce1f4fb80b8', 'The note used circulatory to mark the direction or quality of the finding.', 'circulatory', 'The classroom note used this word to say the finding was relating to blood circulation.', '课堂记录把这一发现写成「循环的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('5b371e6f-a0a6-54a2-a2d1-c7863dec8e44', 'essential_medical:core:respiratory:adjective:ess-core-respiratory-001', '206d1f61-313c-5bfd-83a6-ebe64ca5f4cf', 'Students compared a respiratory pattern with the opposite classroom example.', 'respiratory', 'The classroom note used this word to say the finding was relating to breathing and the airways.', '课堂记录把这一发现写成「呼吸的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('546d87ae-4700-5735-a350-2838e8662f42', 'essential_medical:core:urinary:adjective:ess-core-urinary-001', '547c158e-cb45-5c27-a1a4-f652ea56534d', 'The attending asked whether the process was truly urinary in this patient.', 'urinary', 'The classroom note used this word to say the finding was relating to urine formation and outflow.', '课堂记录把这一发现写成「泌尿的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('7923d05e-391d-52da-b9b5-79f722f0cf78', 'essential_medical:core:endocrine:adjective:ess-core-endocrine-001', '6bd99803-c48f-5aa5-8eff-431f50e0bb9f', 'The tutor called the finding endocrine rather than using a looser bedside word.', 'endocrine', 'The classroom note used this word to say the finding was relating to hormone-secreting glands.', '课堂记录把这一发现写成「内分泌的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('33d2f6ab-07d5-533b-889e-d3289d115bb5', 'essential_medical:core:reproductive:adjective:ess-core-reproductive-001', 'eaeefd91-860a-5465-b243-316870a89266', 'The case stem described a reproductive change that students had to interpret.', 'reproductive', 'The classroom note used this word to say the finding was relating to organs of reproduction.', '课堂记录把这一发现写成「生殖的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('a8e38a91-87e2-5d1e-bd44-7a675f07eb2e', 'essential_medical:core:gastrointestinal:adjective:ess-core-gastrointestinal-001', '400a45f2-c810-533d-ba18-58a4fd62cda4', 'On the ward, the sign was documented as gastrointestinal after the examination.', 'gastrointestinal', 'The classroom note used this word to say the finding was relating to the stomach and intestines.', '课堂记录把这一发现写成「胃肠的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
