  ('83b7cf90-40f6-51f5-893f-52e7e234de85', 'essential_medical:core:colitis:noun:ess-core-colitis-001', '721f31b3-d8ac-5696-97cb-fca5b9788022', 'The ward round paused on the colitis so juniors could name it correctly.', 'colitis', 'Here the term names inflammation of the colon.', '这里指结肠炎。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
