  ('1a637491-acf8-569c-a831-af79b144d5f4', 'essential_medical:core:atonia:noun:ess-core-atonia-001', 'f8bd36ef-f42f-59fe-9e32-7e0fddd25bd6', 'A short case note mentioned the atonia before listing later findings.', 'atonia', 'Here the term names loss of normal muscle tone.', '这里指张力缺乏。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('092a85a0-3d90-5a6f-ae09-5fdca3926464', 'essential_medical:core:subacute:adjective:ess-core-subacute-001', '7f10073f-b90a-5302-981f-5b515077c641', 'The textbook warns not to write subacute unless the evidence actually fits.', 'subacute', 'The classroom note used this word to say the finding was between acute and chronic in time course.', '课堂记录把这一发现写成「亚急性的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('27063f96-e338-5ce7-95b3-ab20230cec26', 'essential_medical:core:epidemic:adjective:ess-core-epidemic-001', '15a45797-9ce1-5964-aaf6-e73fb0da8a49', 'Her presentation stayed epidemic from admission through the first night.', 'epidemic', 'The classroom note used this word to say the finding was spreading widely through a population in a short time.', '课堂记录把这一发现写成「流行的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
