  ('49e5c51d-143b-5ef5-bd56-b941070d8771', 'essential_medical:core:embolus:noun:ess-core-embolus-001', '092179ce-84d8-5ea1-a6bf-dc6e45bb2b54', 'The lecture contrasted a healthy embolus with the diseased counterpart.', 'embolus', 'Here the term names intravascular material that travels and lodges downstream.', '这里指栓子。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('4aa2c020-fa52-5cc5-bdab-f6cb36d7c2a4', 'essential_medical:core:infarct:noun:ess-core-infarct-001', '9d6f7629-ee5a-5867-b447-b7f746a44c4b', 'In class the tutor pointed to the infarct while explaining the adjacent organ.', 'infarct', 'Here the term names an area of tissue killed by ischemia.', '这里指梗死灶。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('ee2b19a5-9e84-5340-a9c0-b1b0e18adfd8', 'essential_medical:core:cardiac-output:phrase:ess-core-cardiac-output-001', '8b7b62d0-cbbb-56aa-ac29-90d0a98b4d53', 'The diagram of the cardiac output was the first figure in that chapter.', 'cardiac output', 'Here the term names the volume of blood the heart pumps per minute.', '这里指心输出量。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('b17dbf5c-be70-5ac8-b3d3-16526c0acb1e', 'essential_medical:core:stroke-volume:phrase:ess-core-stroke-volume-001', '63258748-d4c3-5d74-b671-59ec9067950b', 'On rounds the registrar asked for the function of the stroke volume.', 'stroke volume', 'Here the term names the volume ejected by a ventricle in one beat.', '这里指每搏输出量。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('5ea92f31-8f9e-562b-a47d-0bcd3c980e83', 'essential_medical:core:vena-cava:phrase:ess-core-vena-cava-001', '43201046-6a99-578b-b581-201c9a309952', 'The textbook treats the vena cava as core vocabulary, not exam trivia.', 'vena cava', 'Here the term names the large vein returning blood to the right atrium.', '这里指腔静脉。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('36d1d185-fd82-52d3-b4a3-ef75c0c53242', 'essential_medical:core:mitral:adjective:ess-core-mitral-001', '197f00de-ba5a-5bde-81f9-fce9af491774', 'Her presentation stayed mitral from admission through the first night.', 'mitral', 'The classroom note used this word to say the finding was relating to the left atrioventricular valve.', '课堂记录把这一发现写成「二尖瓣的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('5e90bb1c-6ad8-5895-9f42-e2683180237f', 'essential_medical:core:tricuspid:adjective:ess-core-tricuspid-001', '8dbebd5e-ae46-5f94-95a1-b7c5f3b462df', 'The note used tricuspid to mark the direction or quality of the finding.', 'tricuspid', 'The classroom note used this word to say the finding was relating to the right atrioventricular valve.', '课堂记录把这一发现写成「三尖瓣的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('7294f99f-aa82-590d-801a-9e47a90213fe', 'essential_medical:core:aortic:adjective:ess-core-aortic-001', '608c196c-b5b1-5b39-9c1e-8fb32ee4f847', 'Students compared a aortic pattern with the opposite classroom example.', 'aortic', 'The classroom note used this word to say the finding was relating to the aorta or aortic valve.', '课堂记录把这一发现写成「主动脉的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('007c51a2-4f87-5aec-b36e-a15fa2a2aa8b', 'essential_medical:core:regurgitation:noun:ess-core-regurgitation-001', '5eb3862d-8d99-5f4e-8a51-a931d7184fcc', 'The lecture contrasted a healthy regurgitation with the diseased counterpart.', 'regurgitation', 'Here the term names backward flow through an incompetent valve.', '这里指反流。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('6730fa7d-7723-5b9c-b49f-6093d0e7c26b', 'essential_medical:core:cardiomyopathy:noun:ess-core-cardiomyopathy-001', '9b16d4f3-954f-5e9b-8fbe-95e7c4102172', 'In class the tutor pointed to the cardiomyopathy while explaining the adjacent organ.', 'cardiomyopathy', 'Here the term names primary disease of the heart muscle.', '这里指心肌病。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('8a91ca2d-f259-551b-bd8d-889ee726fb0b', 'essential_medical:core:fibrillation:noun:ess-core-fibrillation-001', '9b96e8c7-968e-5fe7-b6e4-d0f1c29c9cc0', 'The chapter on body structure opens with the fibrillation as a teaching example.', 'fibrillation', 'Here the term names rapid, uncoordinated muscle twitching, as in AF or VF.', '这里指纤颤。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('c08433b8-de84-5e75-921f-dec8497d8773', 'essential_medical:core:asystole:noun:ess-core-asystole-001', 'dcd40554-c450-5959-9f5f-d36ab78c6ecd', 'A short case note mentioned the asystole before listing later findings.', 'asystole', 'Here the term names absence of electrical and mechanical cardiac activity.', '这里指心脏停搏。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('14518ed7-ee3d-5365-bc8b-836a1c143b61', 'essential_medical:core:cardiac-arrest:phrase:ess-core-cardiac-arrest-001', '62124f8c-ea93-5f23-ac79-3e0adfedf91c', 'The case note named the cardiac arrest before describing what happened next.', 'cardiac arrest', 'Here the term names sudden cessation of effective circulation.', '这里指心脏骤停。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('adb5b188-ebb3-567a-a3e0-ce6447c81a2b', 'essential_medical:core:arteriole:noun:ess-core-arteriole-001', '7aa77fc0-8273-5d73-a97b-95fea343daf5', 'The ward round paused on the arteriole so juniors could name it correctly.', 'arteriole', 'Here the term names a small resistance vessel leading to capillaries.', '这里指小动脉。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('7c5c2079-4d8d-5618-a585-ec2f80f65607', 'essential_medical:core:venule:noun:ess-core-venule-001', '0a51ac45-2d97-5b44-ad1c-37619326d0b8', 'The textbook figure labels the venule beside the neighboring tissue.', 'venule', 'Here the term names a small vein draining a capillary bed.', '这里指小静脉。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('457cbe2c-decc-59c1-9676-32bea7396439', 'essential_medical:core:collateral:adjective:ess-core-collateral-001', '0f17cfae-a2b7-59e2-93a0-7379e93a0ee1', 'Students compared a collateral pattern with the opposite classroom example.', 'collateral', 'The classroom note used this word to say the finding was providing an alternative pathway of blood flow.', '课堂记录把这一发现写成「侧支的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('2a6ee929-3cfc-5efd-b8bc-b857f8551d63', 'essential_medical:core:hypertensive:adjective:ess-core-hypertensive-001', '0e1b162a-b5cf-5067-9f42-eeb3e12f134d', 'The attending asked whether the process was truly hypertensive in this patient.', 'hypertensive', 'The classroom note used this word to say the finding was having or causing high blood pressure.', '课堂记录把这一发现写成「高血压的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('240be060-1a5a-5b65-875f-27220f398fa0', 'essential_medical:core:hypotensive:adjective:ess-core-hypotensive-001', '9124ca78-dc2b-5106-9b8d-5cfcaa819fd2', 'The tutor called the finding hypotensive rather than using a looser bedside word.', 'hypotensive', 'The classroom note used this word to say the finding was having or causing low blood pressure.', '课堂记录把这一发现写成「低血压的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('a122e355-d34d-53c6-a62c-0a66e5e0550f', 'essential_medical:core:stethoscope:noun:ess-core-stethoscope-001', '0589d83a-9b52-5be7-997b-0e421288e3b5', 'The chapter on body structure opens with the stethoscope as a teaching example.', 'stethoscope', 'Here the term names the instrument used to listen to heart and lung sounds.', '这里指听诊器。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('74b959f2-8ee4-52fd-a409-2e573dee7700', 'essential_medical:core:sphygmomanometer:noun:ess-core-sphygmomanometer-001', 'b83435b6-4d2d-5731-8561-761fb5292c28', 'A short case note mentioned the sphygmomanometer before listing later findings.', 'sphygmomanometer', 'Here the term names the cuff device used to measure blood pressure.', '这里指血压计。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('5e949d5d-3145-5507-b701-ab1c15942e0a', 'essential_medical:core:orthostatic:adjective:ess-core-orthostatic-001', 'd2c5bbf0-3c38-54d4-acf4-a1df81872a01', 'The textbook warns not to write orthostatic unless the evidence actually fits.', 'orthostatic', 'The classroom note used this word to say the finding was occurring on standing, as in orthostatic hypotension.', '课堂记录把这一发现写成「直立性的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('ddacd913-9a99-5013-ad1e-971d6123c0ac', 'essential_medical:core:bypass:noun:ess-core-bypass-001', '9a1544eb-63b2-5de8-a047-df1131b8918e', 'The ward round paused on the bypass so juniors could name it correctly.', 'bypass', 'Here the term names a grafted route around a blocked vessel.', '这里指旁路；搭桥。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('19776422-347d-5cd7-91a5-6bf9c3eb3c53', 'essential_medical:core:stent:noun:ess-core-stent-001', '590b91a4-be75-58fa-8f94-b6602d736342', 'The textbook figure labels the stent beside the neighboring tissue.', 'stent', 'Here the term names a tube placed to keep a vessel or duct open.', '这里指支架。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('ead57eef-b69f-57c7-b4d6-de0fa38bd7b4', 'essential_medical:core:pacemaker:noun:ess-core-pacemaker-001', '56da35d4-20bf-59f8-b1b2-cb0c2fef08c8', 'After history taking, the intern wrote the pacemaker into the problem list.', 'pacemaker', 'Here the term names a device that sets or supports heart rhythm.', '这里指起搏器。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('0f164059-0861-5fc6-a6c7-120f54605273', 'essential_medical:core:angioplasty:noun:ess-core-angioplasty-001', '0294c6dd-327d-55db-bf48-c899648cc2bc', 'The lecture contrasted a healthy angioplasty with the diseased counterpart.', 'angioplasty', 'Here the term names mechanical widening of a narrowed vessel.', '这里指血管成形术。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('74b21193-44e8-5322-85dc-0813abc562cd', 'essential_medical:core:defibrillation:noun:ess-core-defibrillation-001', '34555fee-2a01-5eac-8c47-13a3d6563112', 'In class the tutor pointed to the defibrillation while explaining the adjacent organ.', 'defibrillation', 'Here the term names an electric shock to restore an organized rhythm.', '这里指除颤。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('9e0e4f88-131b-5474-b250-aa021040b1d7', 'essential_medical:core:cardioversion:noun:ess-core-cardioversion-001', '24a78f6a-0179-5349-ba90-7d10732e8572', 'The chapter on body structure opens with the cardioversion as a teaching example.', 'cardioversion', 'Here the term names timed shock or drug use to restore sinus rhythm.', '这里指心脏复律。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('0147756b-9a35-5579-9f41-5805fc6226e0', 'essential_medical:core:resuscitation:noun:ess-core-resuscitation-001', '7098919e-4af6-51aa-b94d-31b7e7b14ba3', 'A short case note mentioned the resuscitation before listing later findings.', 'resuscitation', 'Here the term names emergency restoration of circulation and breathing.', '这里指复苏。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('6ca1d1e4-712d-59cb-b4ee-486d50c13bdc', 'essential_medical:core:atheroma:noun:ess-core-atheroma-001', '571c8ee9-9802-5382-be72-96aa17b0a42b', 'Students were asked to locate the atheroma on the classroom diagram.', 'atheroma', 'Here the term names the lipid-rich plaque of atherosclerosis.', '这里指粥样斑块。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('cbb1160e-22c5-5e7c-a13c-8f2831501ed5', 'essential_medical:core:ischemic:adjective:ess-core-ischemic-001', '8cdaa08d-c111-5442-8223-dedc78fa9137', 'Her presentation stayed ischemic from admission through the first night.', 'ischemic', 'The classroom note used this word to say the finding was caused by or related to inadequate blood flow.', '课堂记录把这一发现写成「缺血性的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('53ab458f-daa8-566b-8651-62479946a7ea', 'essential_medical:core:hemorrhagic:adjective:ess-core-hemorrhagic-001', 'c212b4cd-6861-56c1-9571-6844a708d399', 'The note used hemorrhagic to mark the direction or quality of the finding.', 'hemorrhagic', 'The classroom note used this word to say the finding was caused by or related to bleeding.', '课堂记录把这一发现写成「出血性的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('d6eaacb1-200f-5434-b299-ddb128098ca2', 'essential_medical:core:congestive:adjective:ess-core-congestive-001', '9dedc9ec-da57-52b6-b8a7-7b4080df6e89', 'Students compared a congestive pattern with the opposite classroom example.', 'congestive', 'The classroom note used this word to say the finding was marked by vascular congestion, as in heart failure.', '课堂记录把这一发现写成「充血性的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('c13a5ee3-055f-5d40-bdf2-8d34a425e9c4', 'essential_medical:core:preload:noun:ess-core-preload-001', '3a3ca8dc-c6ed-57f5-ad39-39ad6e0144c6', 'The lecture contrasted a healthy preload with the diseased counterpart.', 'preload', 'Here the term names the stretch of ventricle at the end of filling.', '这里指前负荷。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('d175df6d-ae1a-53e5-ae94-35e186776822', 'essential_medical:core:afterload:noun:ess-core-afterload-001', '9c2d238c-5044-5397-a62d-c8ad10531926', 'In class the tutor pointed to the afterload while explaining the adjacent organ.', 'afterload', 'Here the term names the resistance the ventricle must overcome to eject.', '这里指后负荷。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('caac98d0-3a32-542d-ad1b-30a269f7a92c', 'essential_medical:core:contractility:noun:ess-core-contractility-001', '42126b41-06be-531f-ad55-d64b817452b8', 'The chapter on body structure opens with the contractility as a teaching example.', 'contractility', 'Here the term names the intrinsic strength of muscle contraction.', '这里指收缩性。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('c75f43ff-031a-5190-8d2f-29fc3aed224e', 'essential_medical:core:bronchiole:noun:ess-core-bronchiole-001', '94f5ec51-6e46-5bb7-82fe-c0b2e5422258', 'A short case note mentioned the bronchiole before listing later findings.', 'bronchiole', 'Here the term names a small airway distal to the bronchi.', '这里指细支气管。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('507ab76e-5159-5e4f-9332-c2a0e297bd0b', 'essential_medical:core:emphysema:noun:ess-core-emphysema-001', 'b66b2f50-9af5-5e80-bcdd-0170f827ac95', 'Students were asked to locate the emphysema on the classroom diagram.', 'emphysema', 'Here the term names destruction of alveolar walls with air trapping.', '这里指肺气肿。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('71a9286e-09fd-5634-ac56-ae1048ed6614', 'essential_medical:core:hypoxemia:noun:ess-core-hypoxemia-001', '0d877b75-f635-5ea7-b3a9-67f4586a7e44', 'The ward round paused on the hypoxemia so juniors could name it correctly.', 'hypoxemia', 'Here the term names low oxygen content or tension in arterial blood.', '这里指低氧血症。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('50b2c540-c09e-5c37-ab1c-dbdb29693967', 'essential_medical:core:hypercapnia:noun:ess-core-hypercapnia-001', '5d9ba301-65f1-5d1f-81b9-5a8a05fe6cc2', 'The textbook figure labels the hypercapnia beside the neighboring tissue.', 'hypercapnia', 'Here the term names excess carbon dioxide in the blood.', '这里指高碳酸血症。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('559f174c-a470-5e59-828c-3066cf188b45', 'essential_medical:core:bradypnea:noun:ess-core-bradypnea-001', '7507e088-16cd-518a-bcb3-936e4acb8a08', 'After history taking, the intern wrote the bradypnea into the problem list.', 'bradypnea', 'Here the term names an abnormally slow respiratory rate.', '这里指呼吸过缓。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('65e95424-6c36-5e14-9e1c-76af2a28ee2f', 'essential_medical:core:crackle:noun:ess-core-crackle-001', 'b3827993-7eb8-5338-be72-612cd28f0054', 'The lecture contrasted a healthy crackle with the diseased counterpart.', 'crackle', 'Here the term names a discontinuous lung sound of opening alveoli or fluid.', '这里指爆裂音。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('53bea70d-b276-5158-a6e7-163b1c352c0d', 'essential_medical:core:surfactant:noun:ess-core-surfactant-001', '8d2c398b-1081-5ec1-8e3a-8182137a77e8', 'In class the tutor pointed to the surfactant while explaining the adjacent organ.', 'surfactant', 'Here the term names the alveolar lining that lowers surface tension.', '这里指表面活性物质。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('3626a4cf-4ef0-5382-b84f-88eb839edfd4', 'essential_medical:core:intercostal:adjective:ess-core-intercostal-001', 'c0fab26c-97dd-526d-bf1a-92ef5a31c9b3', 'The case stem described a intercostal change that students had to interpret.', 'intercostal', 'The classroom note used this word to say the finding was between the ribs.', '课堂记录把这一发现写成「肋间的」。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('58b2bd4f-805a-51cd-994b-a47beda81857', 'essential_medical:core:mediastinum:noun:ess-core-mediastinum-001', '104aeb66-d00c-5bf2-84cd-514b8b558069', 'A short case note mentioned the mediastinum before listing later findings.', 'mediastinum', 'Here the term names the central chest compartment between the lungs.', '这里指纵隔。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null),
  ('20fd22aa-2d8a-54cc-80a2-3864e29051ff', 'essential_medical:core:asphyxia:noun:ess-core-asphyxia-001', '19766348-0dbe-5104-8129-c81f91692283', 'Students were asked to locate the asphyxia on the classroom diagram.', 'asphyxia', 'Here the term names failure of gas exchange with life-threatening hypoxia.', '这里指窒息。', array[]::text[], 'medical_textbook', 'original_example', null, null, null, null)
